function compress(s) {
  if (s == null || s.length === 0) return s;
  const out = [];
  for (let i = 0; i < s.length;) {
    let j = i + 1;
    while (j < s.length && s[j] === s[i]) j++;
    out.push(s[i], j - i > 1 ? String(j - i) : ''); i = j;
  }
  const result = out.join('');
  return result.length < s.length ? result : s;
}

