class HashTable {
  constructor(size = 16) {
    if (!Number.isInteger(size) || size < 1) throw new RangeError('Positive table size required');
    this.buckets = Array.from({length: size}, () => []);
  }
  bucket(key) { return this.buckets[((key % this.buckets.length) + this.buckets.length) % this.buckets.length]; }
  set(key, value) {
    const bucket = this.bucket(key), entry = bucket.find(item => item.key === key);
    if (entry) entry.value = value; else bucket.push({key, value});
  }
  get(key) {
    const entry = this.bucket(key).find(item => item.key === key);
    if (!entry) throw new Error('Key not found');
    return entry.value;
  }
  remove(key) {
    const bucket = this.bucket(key), index = bucket.findIndex(item => item.key === key);
    if (index < 0) throw new Error('Key not found');
    bucket.splice(index, 1);
  }
}

