class ArrayPriorityQueue {
  constructor() { this.items = []; }
  insert(key, priority) { const node = {key, priority}; this.items.push(node); return node; }
  extractMin() {
    if (!this.items.length) return null;
    let best = 0;
    for (let i = 1; i < this.items.length; i++) if (this.items[i].priority < this.items[best].priority) best = i;
    return this.items.splice(best, 1)[0];
  }
  decreaseKey(key, priority) {
    const node = this.items.find(item => item.key === key);
    if (!node) return null;
    if (priority > node.priority) throw new RangeError('Priority must decrease');
    node.priority = priority; return node;
  }
}

