class MultiStack {
  constructor(count, capacity) {
    if (!Number.isInteger(count) || !Number.isInteger(capacity) || count < 1 || capacity < 1) throw new RangeError('Positive sizes required');
    this.capacity = capacity; this.sizes = Array(count).fill(0); this.values = Array(count * capacity);
  }
  push(stack, value) {
    if (this.sizes[stack] === this.capacity) throw new RangeError('Stack full');
    this.values[stack * this.capacity + this.sizes[stack]++] = value;
  }
  pop(stack) {
    if (this.sizes[stack] === 0) throw new RangeError('Stack empty');
    const index = stack * this.capacity + --this.sizes[stack], value = this.values[index];
    this.values[index] = undefined; return value;
  }
}

