function buildOrder(projects, dependencies) {
  const edges = new Map(projects.map(p => [p, new Set()])), degree = new Map(projects.map(p => [p,0]));
  for (const [before, after] of dependencies) if (!edges.get(before).has(after)) {
    edges.get(before).add(after); degree.set(after, degree.get(after) + 1);
  }
  const order = projects.filter(p => degree.get(p) === 0);
  for (let i = 0; i < order.length; i++) for (const next of edges.get(order[i])) {
    degree.set(next, degree.get(next) - 1); if (degree.get(next) === 0) order.push(next);
  }
  return order.length === projects.length ? order : null;
}

