function subtractWithoutArithmetic(a,b) {
  if (typeof a !== 'bigint' || typeof b !== 'bigint') throw new TypeError('BigInt inputs required');
  const width=Math.max(a.toString(2).length,b.toString(2).length)*2;
  a=BigInt.asUintN(width,a); b=BigInt.asUintN(width,b);
  while (b!==0n) {
    const borrow=BigInt.asUintN(width,(~a & b) << 1n);
    a=BigInt.asUintN(width,a ^ b); b=borrow;
  }
  return BigInt.asIntN(width,a);
}

