function twoSum(values,target) {
  if (!Array.isArray(values)) throw new TypeError('Array required');
  if (values.length<2) throw new RangeError('At least two values required');
  const indices=new Map();
  for (let i=0;i<values.length;i++) {
    const needed=target-values[i];
    if (indices.has(needed)) return [indices.get(needed),i];
    indices.set(values[i],i);
  }
  return null;
}

