function validateItems(items,capacity) {
  if (!Array.isArray(items) || !Number.isInteger(capacity)) throw new TypeError('Items and integer capacity required');
  if (capacity<0 || items.some(item=>!Number.isInteger(item.weight) || item.weight<=0 || !Number.isFinite(item.value) || item.value<=0)) throw new RangeError('Positive item weights/values and nonnegative capacity required');
}

function chooseKnapsackItems(items,capacity) {
  validateItems(items,capacity);
  const n=items.length, dp=Array.from({length:n+1},()=>Array(capacity+1).fill(0));
  for (let i=1;i<=n;i++) for (let w=0;w<=capacity;w++) {
    const item=items[i-1]; dp[i][w]=dp[i-1][w];
    if (item.weight<=w) dp[i][w]=Math.max(dp[i][w],item.value+dp[i-1][w-item.weight]);
  }
  const indices=[]; let remaining=capacity;
  for (let i=n;i>0;i--) if (dp[i][remaining]!==dp[i-1][remaining]) { indices.push(i-1); remaining-=items[i-1].weight; }
  indices.reverse();
  return {value:dp[n][capacity],indices,items:indices.map(i=>items[i])};
}

