function unboundedKnapsack(items,capacity) {
  validateItems(items,capacity);
  const dp=Array(capacity+1).fill(0);
  for (let w=1;w<=capacity;w++) for (const item of items) if (item.weight<=w) dp[w]=Math.max(dp[w],dp[w-item.weight]+item.value);
