class Graph {
  constructor(directed = true) { this.directed = directed; this.edges = new Map(); }
  addNode(key) { if (!this.edges.has(key)) this.edges.set(key, new Map()); return this; }
  addEdge(from, to, weight = 1) {
    this.addNode(from); this.addNode(to);
    this.edges.get(from).set(to, weight);
    if (!this.directed) this.edges.get(to).set(from, weight);
    return this;
  }
  removeEdge(from, to) {
    this.edges.get(from)?.delete(to);
    if (!this.directed) this.edges.get(to)?.delete(from);
  }
  removeNode(key) {
    this.edges.delete(key);
    for (const neighbors of this.edges.values()) neighbors.delete(key);
  }
}

function shortestUnweightedPath(graph,start,end) {
  if (!graph.edges.has(start) || !graph.edges.has(end)) return null;
  const queue=[start], previous=new Map([[start,null]]);
  for (let i=0;i<queue.length;i++) {
    const node=queue[i];
    if (node===end) {
      const path=[end]; let current=end;
      while (current!==start) { current=previous.get(current); path.push(current); }
      return path.reverse();
    }
    for (const next of graph.edges.get(node).keys()) if (!previous.has(next)) { previous.set(next,node); queue.push(next); }
  }
  return null;
}

