function longestSubstringWithKDistinct(text,k) {
  if (typeof text !== 'string' || !Number.isInteger(k)) throw new TypeError('String and integer k required');
  if (k<0) throw new RangeError('Nonnegative k required');
  if (k===0) return 0;
  const chars=Array.from(text), counts=new Map(); let left=0,best=0;
  for (let right=0;right<chars.length;right++) {
    counts.set(chars[right],(counts.get(chars[right])??0)+1);
    while (counts.size>k) {
      const ch=chars[left++], count=counts.get(ch)-1;
      if (count===0) counts.delete(ch); else counts.set(ch,count);
    }
    best=Math.max(best,right-left+1);
  }
  return best;
}

