function longestAbsoluteFilePath(input) {
  if (typeof input !== 'string') throw new TypeError('String required');
  const lengths=[0]; let best=0;
  for (const line of input.split('\n')) {
    let depth=0; while (line[depth]==='\t') depth++;
    const name=line.slice(depth);
    if (lengths[depth]===undefined) throw new RangeError('Invalid indentation');
    const length=lengths[depth]+name.length;
    if (name.includes('.')) best=Math.max(best,length);
    else lengths[depth+1]=length+1;
    lengths.length=depth+2;
  }
  return best;
}

