function sentenceFits(sentence,rows,cols) {
  if (!Array.isArray(sentence) || !Number.isInteger(rows) || !Number.isInteger(cols)) throw new TypeError('Word array and integer dimensions required');
  if (rows<0 || cols<0) throw new RangeError('Nonnegative dimensions required');
  if (!sentence.length || rows===0 || cols===0) return 0;
  if (sentence.some(word=>typeof word!=='string' || !word.length)) throw new TypeError('Nonempty words required');
  if (sentence.some(word=>word.length>cols)) return 0;
  const text=sentence.join(' ')+' '; let position=0;
  for (let row=0;row<rows;row++) {
    position+=cols;
    if (text[position%text.length]===' ') position++;
    else while (position>0 && text[(position-1)%text.length]!==' ') position--;
  }
  return Math.floor(position/text.length);
}

