function formatLicenseKey(input,k) {
  if (typeof input !== 'string' || !Number.isInteger(k)) throw new TypeError('String and integer k required');
  if (k<=0) throw new RangeError('Positive group size required');
  const clean=input.replaceAll('-','').toUpperCase(), groups=[];
