function busiestPeriod(events) {
  if (!Array.isArray(events)) throw new TypeError('Events required');
  if (!events.length) return null;
  const sorted=events.map(event=>event.slice()).sort((a,b)=>a[0]-b[0]);
  let occupancy=0,maximum=0,result=[0,0];
  for (let i=0;i<sorted.length;) {
    const timestamp=sorted[i][0];
    while (i<sorted.length && sorted[i][0]===timestamp) {
      const [,people,type]=sorted[i++];
      if (type==='ENTER') occupancy+=people;
      else if (type==='EXIT') occupancy-=people;
      else throw new RangeError('Use ENTER or EXIT');
    }
    if (occupancy>maximum) { maximum=occupancy; result=[timestamp,i<sorted.length ? sorted[i][0] : timestamp]; }
  }
  return result;
}

