class MinHeap {
  constructor(compare = (a, b) => a - b) { this.items = []; this.compare = compare; }
  insert(value) {
    const a = this.items; a.push(value);
    let i = a.length - 1;
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (this.compare(a[p], a[i]) <= 0) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  extractMin() {
    const a = this.items;
    if (!a.length) return null;
    const result = a[0], last = a.pop();
    if (!a.length) return result;
    a[0] = last; let i = 0;
    while (true) {
      let best = i;
      const left = 2 * i + 1, right = left + 1;
      if (left < a.length && this.compare(a[left], a[best]) < 0) best = left;
      if (right < a.length && this.compare(a[right], a[best]) < 0) best = right;
      if (best === i) break;
      [a[i], a[best]] = [a[best], a[i]]; i = best;
    }
    return result;
  }
}

